function freshState(){
  return {version:4,onboarded:false,profile:{name:'Reader',path:'rider',points:0,rankIndex:0,assessment:null,assessmentSealed:false,eventComplete:false,bond:null,pendingBondReveal:false,bondRevealSeen:false},pathRecords:{},usedCreatureNames:[],books:[],sessions:[],theories:[],suspicions:[],walls:[{id:'main',name:'Master Wall',description:'The central web of every unresolved connection.',categories:['Theory','Suspicion','Character','Dragon','Gryphon','Wyvern','Book','Evidence','Artifact','Location','Faction','Question','Event']}],activeWallId:'main',wallCards:[],wallLinks:[],currentSession:null};
}
function loadState(){
  const raw=localStorage.getItem(STORAGE_KEY); if(raw){try{return normalizeState(JSON.parse(raw));}catch(e){}}
  const legacy=localStorage.getItem(LEGACY_KEY); if(legacy){try{return migrateLegacy(JSON.parse(legacy));}catch(e){}}
  return freshState();
}
function normalizeState(s){ const n={...freshState(),...s}; n.profile={...freshState().profile,...(s.profile||{})}; n.pathRecords=(s.pathRecords&&typeof s.pathRecords==='object')?s.pathRecords:{}; ['usedCreatureNames','books','sessions','theories','suspicions','walls','wallCards','wallLinks'].forEach(k=>n[k]=Array.isArray(n[k])?n[k]:[]); if(!n.pathRecords[n.profile.path])n.pathRecords[n.profile.path]=pathRecordFromProfile(n.profile); Object.values(n.pathRecords).forEach(r=>{if(r?.bond?.name&&!n.usedCreatureNames.some(x=>String(x).toLowerCase()===String(r.bond.name).toLowerCase()))n.usedCreatureNames.push(r.bond.name);}); if(n.profile.bond?.name&&!n.usedCreatureNames.some(x=>String(x).toLowerCase()===String(n.profile.bond.name).toLowerCase()))n.usedCreatureNames.push(n.profile.bond.name); if(!n.walls.length)n.walls=freshState().walls; if(!n.activeWallId||!n.walls.some(w=>w.id===n.activeWallId))n.activeWallId=n.walls[0].id; n.version=4; return n; }
function migrateLegacy(old){ const n=freshState(); n.onboarded=!!old.onboarded; n.profile={...n.profile,...old.profile,assessmentSealed:!!old.profile?.assessment,eventComplete:old.profile?.rankIndex>=2,bond:old.profile?.creatureName?{name:old.profile.creatureName,type:old.profile.creatureType||'Companion',ability:old.profile.signet}:null}; n.books=old.books||[]; n.sessions=old.sessions||[]; n.theories=old.theories||[]; n.currentSession=old.currentSession||null; if(n.profile.bond?.name)n.usedCreatureNames=[n.profile.bond.name]; n.pathRecords[n.profile.path]=pathRecordFromProfile(n.profile); n.wallCards=(old.wallCards||[]).map(c=>({...c,wallId:'main',category:c.type||'Evidence',sourceType:c.sourceId?'theory':'custom'})); return n; }
let state=loadState(),activeView='dashboard',sessionTimer=null,sessionSeconds=0,selectedPath='rider';

function blankPathRecord(pathKey){
  return {points:0,rankIndex:0,assessment:null,assessmentSealed:false,eventComplete:!['rider','gryphon'].includes(pathKey),bond:null,pendingBondReveal:false,bondRevealSeen:false};
}
function pathRecordFromProfile(profile){
  profile=profile||{};
  return {points:Number(profile.points)||0,rankIndex:Number(profile.rankIndex)||0,assessment:profile.assessment||null,assessmentSealed:!!profile.assessmentSealed,eventComplete:!!profile.eventComplete,bond:profile.bond?{...profile.bond}:null,pendingBondReveal:!!profile.pendingBondReveal,bondRevealSeen:!!profile.bondRevealSeen};
}
function saveCurrentPathRecord(){
  state.pathRecords=state.pathRecords&&typeof state.pathRecords==='object'?state.pathRecords:{};
  state.pathRecords[state.profile.path]=pathRecordFromProfile(state.profile);
}
function restorePathRecord(pathKey){
  state.pathRecords=state.pathRecords&&typeof state.pathRecords==='object'?state.pathRecords:{};
  const record=state.pathRecords[pathKey]||blankPathRecord(pathKey);
  state.pathRecords[pathKey]=record;
  Object.assign(state.profile,{path:pathKey,points:record.points||0,rankIndex:record.rankIndex||0,assessment:record.assessment||null,assessmentSealed:!!record.assessmentSealed,eventComplete:!!record.eventComplete,bond:record.bond?{...record.bond}:null,pendingBondReveal:!!record.pendingBondReveal,bondRevealSeen:!!record.bondRevealSeen});
  recalcRank();
}

function saveState(){saveCurrentPathRecord();localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function path(){return PATHS[state.profile.path]||PATHS.rider;}
function copy(k){return path().copy[k]||k;}
function uid(){return `${Date.now().toString(36)}${Math.random().toString(36).slice(2,8)}`;}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function showToast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('is-visible');setTimeout(()=>t.classList.remove('is-visible'),2600);}
function openModal(id='formModal'){const e=document.getElementById(id);e.classList.add('is-open');e.setAttribute('aria-hidden','false');}
function closeModal(id='formModal'){const e=document.getElementById(id);e.classList.remove('is-open');e.setAttribute('aria-hidden','true');}
function currentRank(){return path().ranks[state.profile.rankIndex]||path().ranks.at(-1);}
function recalcRank(){ const t=path().thresholds; let i=0; t.forEach((v,x)=>{if(state.profile.points>=v)i=x;}); if(path().bondedRank!==null && state.profile.path!=='dark' && !state.profile.eventComplete)i=Math.min(i,1); state.profile.rankIndex=Math.min(i,path().ranks.length-1); }
function award(n,msg){const before=state.profile.rankIndex;state.profile.points+=Math.max(0,n);recalcRank();saveState();applyTheme();if(state.profile.rankIndex>before)showToast(`Promoted to ${currentRank()}.`);else showToast(msg||`+${n} ${path().progressName}`);}

function init(){buildPathGrid();bindGlobal();if(!state.onboarded)openModal('onboardingModal');applyTheme();renderAll();setTimeout(()=>{if(state.onboarded&&state.profile.pendingBondReveal&&state.profile.bond&&!state.profile.bond.sealed)showBondingRevealModal();},50);}
function buildPathGrid(){const g=document.getElementById('pathGrid');g.innerHTML=Object.entries(PATHS).map(([k,p])=>`<button class="path-choice" data-path-choice="${k}"><span style="font-size:30px">${p.glyph}</span><strong>${p.name}</strong><small>${p.copy.heroBody}</small></button>`).join('');g.querySelectorAll('[data-path-choice]').forEach(b=>b.addEventListener('click',()=>{selectedPath=b.dataset.pathChoice;g.querySelectorAll('.path-choice').forEach(x=>x.classList.toggle('is-selected',x===b));}));}
function bindGlobal(){
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));
  document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>closeModal(b.dataset.closeModal)));
  document.getElementById('quickMarkBtn').addEventListener('click',()=>openQuickMark());
  document.getElementById('profileChip').addEventListener('click',()=>switchView('profile'));
  document.getElementById('continueOnboarding').addEventListener('click',continueOnboarding);
  document.getElementById('backOnboarding').addEventListener('click',()=>setOnboardingStep(1));
  document.getElementById('finishOnboarding').addEventListener('click',finishOnboarding);
  document.getElementById('enterArchive').addEventListener('click',()=>{state.onboarded=true;saveState();closeModal('onboardingModal');renderAll();});
  document.getElementById('resetApp').addEventListener('click',()=>{if(confirm('Erase all locally saved archive data?')){localStorage.removeItem(STORAGE_KEY);localStorage.removeItem(LEGACY_KEY);location.reload();}});
}
function continueOnboarding(){const name=document.getElementById('readerName').value.trim();if(!name||!selectedPath)return showToast('Choose a name and path.');state.profile.name=name;restorePathRecord(selectedPath);const needs=['rider','gryphon','dark'].includes(selectedPath);if(needs&&state.profile.assessment){document.getElementById('assignmentResult').innerHTML=state.profile.bond&&!state.profile.bond.sealed?bondRevealHtml(state.profile.bond,state.profile.path==='dark'):`<div class="result-sigil">✦</div><p class="eyebrow">Assignment restored</p><h2>Your sealed result is still on record.</h2><p>Your previous ${path().name} assessment, progression, bond, signet, relic, and uploaded images have been restored exactly as they were.</p>`;saveState();setOnboardingStep(3);}else if(needs){renderQuestionnaire();setOnboardingStep(2);}else{state.profile.assessmentSealed=false;state.profile.eventComplete=true;document.getElementById('assignmentResult').innerHTML=`<div class="result-sigil">${path().glyph}</div><p class="eyebrow">Path accepted</p><h2>${path().name}</h2><p>You enter as <strong>${path().ranks[0]}</strong>. Every tool is available. Your path changes only the world surrounding it.</p>`;saveState();setOnboardingStep(3);}}
function renderQuestionnaire(){document.getElementById('quizIntro').innerHTML=`<p class="eyebrow">Sealed assessment</p><h2>${path().name} Compatibility Examination</h2><p>Your answers are recorded now, but ${state.profile.path==='dark'?'the source will answer immediately':'the result remains sealed until '+path().event+'.'}</p>`;document.getElementById('quizQuestions').innerHTML=QUESTIONNAIRE.map((x,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${x.q}</legend>${x.a.map((a,j)=>`<label><input type="radio" name="q${i}" value="${j}"><span>${a[0]}</span></label>`).join('')}</fieldset>`).join('');}
function finishOnboarding(){const scores={};for(let i=0;i<QUESTIONNAIRE.length;i++){const c=document.querySelector(`input[name=q${i}]:checked`);if(!c)return showToast('Complete every question before sealing the assessment.');Object.entries(QUESTIONNAIRE[i].a[Number(c.value)][1]).forEach(([k,v])=>scores[k]=(scores[k]||0)+v);}state.profile.assessment=scores;state.profile.assessmentSealed=true;const result=generateBondResult(state.profile.path,scores);if(state.profile.path==='dark'){state.profile.bond=result;state.profile.eventComplete=true;state.profile.rankIndex=0;document.getElementById('assignmentResult').innerHTML=bondRevealHtml(result,true);}else{state.profile.bond={...result,sealed:true};state.profile.eventComplete=false;document.getElementById('assignmentResult').innerHTML=`<div class="result-sigil">✦</div><p class="eyebrow">Assessment sealed</p><h2>Your result has been withheld.</h2><p>You enter as <strong>${path().ranks[0]}</strong>. Complete orientation, advance to ${path().ranks[1]}, and survive <strong>${path().event}</strong> before your bond, relic, and ability are revealed.</p>`;}saveState();setOnboardingStep(3);}
function generateBondResult(kind,s){const top=(obj)=>Object.entries(obj).sort((a,b)=>b[1]-a[1])[0]?.[0];const signet=SIGNETS.map(x=>({x,score:(s[x[2]]||0)+Math.random()*2})).sort((a,b)=>b.score-a.score)[0].x;if(kind==='rider'){const color=Object.values(DRAGONS).map(d=>({d,score:d.keys.reduce((n,k)=>n+(s[k]||0),0)+Math.random()*3})).sort((a,b)=>b.score-a.score)[0].d;const tail=Object.values(TAILS).map(d=>({d,score:d.keys.reduce((n,k)=>n+(s[k]||0),0)+Math.random()*2})).sort((a,b)=>b.score-a.score)[0].d;return {type:'Dragon',name:uniqueCreatureName('Dragon'),color:color.name,subtype:tail.name,description:`${color.desc} ${tail.desc}`,ability:signet[0],abilityDesc:signet[1],relic:'A dragon relic marking the bond.'};}if(kind==='gryphon'){const g=GRYPHONS.map(x=>({x,score:(s[x[2]]||0)+Math.random()*2})).sort((a,b)=>b.score-a.score)[0].x;const mindSignets=SIGNETS.filter(x=>['mind','empathy','intuition','cunning'].includes(x[2]));const m=mindSignets.map(x=>({x,score:(s[x[2]]||0)+Math.random()*2})).sort((a,b)=>b.score-a.score)[0].x;return {type:'Gryphon',name:uniqueCreatureName('Gryphon'),color:g[0],subtype:'Lesser magic channel',description:g[1],ability:m[0],abilityDesc:m[1],relic:'A flier mark earned through the bond.'};}const fire=['green','red','blue'].map(c=>({c,score:(c==='green'?s.unpredictable:c==='red'?s.aggression:s.power)||0+Math.random()*2})).sort((a,b)=>b.score-a.score)[0].c;return {type:'Wyvern',name:uniqueCreatureName('Wyvern'),color:'Grey',subtype:`${fire[0].toUpperCase()+fire.slice(1)} fire`,description:`Two-legged grey wyvern. ${WYVERN_FIRE[fire]}`,ability:signet[0],abilityDesc:signet[1],relic:'The mark of channeling from the source.'};}
const CREATURE_NAMES={
  Dragon:['Aevrith','Bhaelor','Caeraxis','Draevyn','Eryndor','Faelthar','Ghaerion','Ilyrath','Kaervyx','Maeloran','Nythara','Oryndrax','Rhaevor','Syraxen','Taelith','Vaeraxis','Xevrion','Zhaerith'],
  Gryphon:['Aurelune','Brannoc','Caelwyn','Duskfeather','Eircrest','Falkren','Galeheart','Highmere','Kestrelis','Larkspur','Mistralyn','Oakenwing','Peregrin','Rookvale','Skylance','Tawnycrest','Windmere','Zephyrclaw'],
  Wyvern:['Ashmaw','Blightwing','Cindervein','Dreadcoil','Emberrot','Gravespine','Hollowfang','Ironhunger','Mireclaw','Nightscar','Ruinflame','Sablemaw','Scorchvein','Vilethorn','Voidfang','Wraithscale','Xalgrave','Zerothane']
};
function uniqueCreatureName(type){
  state.usedCreatureNames=Array.isArray(state.usedCreatureNames)?state.usedCreatureNames:[];
  const used=new Set(state.usedCreatureNames.map(x=>String(x).toLowerCase()));
  const available=(CREATURE_NAMES[type]||[]).filter(x=>!used.has(x.toLowerCase()));
  let name=available[Math.floor(Math.random()*available.length)];
  if(!name){let i=2;const base=(CREATURE_NAMES[type]||[type])[0];while(used.has(`${base} ${i}`.toLowerCase()))i++;name=`${base} ${i}`;}
  state.usedCreatureNames.push(name);
  return name;
}
function bondRevealHtml(b,dark=false){return `<div class="result-sigil">${dark?'🐲':path().glyph}</div><p class="eyebrow">${dark?'The source answers':'Bond established'}</p><h2>${esc(b.name)}</h2><p><strong>${esc(b.color)} ${esc(b.type)}</strong> · ${esc(b.subtype)}</p><p>${esc(b.description)}</p><div class="result-card"><strong>${esc(b.ability)}</strong><p>${esc(b.abilityDesc)}</p></div>`;}
function setOnboardingStep(n){document.querySelectorAll('.onboarding-step').forEach(x=>x.classList.toggle('is-active',x.dataset.step==n));}

function switchView(v){activeView=v;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('is-active',b.dataset.view===v));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('is-visible',x.id===v));renderView(v);applyTheme();}
function applyTheme(){const p=path(),pathKey=state.profile.path;document.getElementById('app').dataset.path=pathKey;document.body.dataset.path=pathKey;document.querySelectorAll('.modal-backdrop').forEach(element=>element.dataset.path=pathKey);document.querySelectorAll('[data-copy]').forEach(e=>e.textContent=copy(e.dataset.copy));document.getElementById('topEyebrow').textContent=p.short;document.getElementById('viewTitle').textContent=copy({dashboard:'navDashboard',library:'navLibrary',session:'navSession',theories:'navTheories',wall:'navWall',profile:'navProfile'}[activeView]);document.getElementById('sidebarRank').textContent=currentRank();document.getElementById('profilePath').textContent=p.name;document.getElementById('profileName').textContent=state.profile.name;document.getElementById('profileInitial').textContent=(state.profile.name||'R')[0].toUpperCase();}
function renderAll(){recalcRank();applyTheme();renderView(activeView);}
function renderView(v){({dashboard:renderDashboard,library:renderLibrary,session:renderSession,theories:renderTheories,wall:renderWall,profile:renderProfile}[v]||renderDashboard)();}

function renderDashboard(){const el=document.getElementById('dashboard');const active=state.books.find(b=>b.status==='reading');const unresolved=state.theories.filter(t=>!['Confirmed','Disproven'].includes(t.status)).length;const eventReady=['rider','gryphon'].includes(state.profile.path)&&!state.profile.eventComplete&&state.profile.points>=path().thresholds[2];el.innerHTML=`<section class="hero-panel"><div><p class="eyebrow">${path().short}</p><h3>${copy('heroTitle')}</h3><p>${copy('heroBody')}</p><div class="button-row"><button class="primary-button" data-action="add-book">${copy('addBook')}</button><button class="secondary-button" data-action="quick-mark">Quick Mark</button></div></div><div class="hero-sigil">${path().glyph}</div></section>${eventReady?`<section class="event-banner"><div><p class="eyebrow">Rank event available</p><h3>${path().event} awaits.</h3><p>Your sealed assessment is ready to be revealed, but only after the event.</p></div><button class="primary-button" data-action="path-event">Begin ${path().event}</button></section>`:''}<div class="metric-grid"><div class="metric-card"><span>Books</span><strong>${state.books.length}</strong></div><div class="metric-card"><span>Open theories</span><strong>${unresolved}</strong></div><div class="metric-card"><span>Suspicions</span><strong>${state.suspicions.length}</strong></div><div class="metric-card"><span>Walls</span><strong>${state.walls.length}</strong></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h3>Active reading</h3><button class="text-button" data-action="view-library">View all</button></div>${active?bookCard(active,true):`<p>${copy('noBooks')}</p>`}</section><section class="panel"><div class="panel-header"><h3>Latest intelligence</h3><button class="text-button" data-action="add-theory">Add</button></div>${state.theories.slice(-3).reverse().map(theoryCard).join('')||`<p>${copy('noTheories')}</p>`}</section></div>`;bindActions(el);}
function renderLibrary(){
  const el=document.getElementById('library'),previous=state.libraryPreferences||{},prefs=state.libraryPreferences={sort:previous.sort||'added',group:previous.group||'none',layout:previous.layout||'list',size:previous.size||'standard',showCover:previous.showCover??true,showCreator:previous.showCreator??true,showStatus:previous.showStatus??true,showProgress:previous.showProgress??true,showRating:previous.showRating??true,showSpice:previous.showSpice??true,showImpact:previous.showImpact??true,showLiked:previous.showLiked??true};
  const visibility=[['Cover','showCover'],['Author & series','showCreator'],['Reading status','showStatus'],['Progress','showProgress'],['Overall rating','showRating'],['Spice rating','showSpice'],['Emotional impact','showImpact'],['Liked state','showLiked']];
  el.innerHTML=`<div class="library-toolbar"><label class="library-search">Search<input class="search-input" id="bookSearch" placeholder="Titles, authors, or series"></label><label>Organize by<select id="librarySort"><option value="added">Date added</option><option value="title">Title</option><option value="author">Author</option><option value="status">Reading status</option><option value="rating">Highest rating</option><option value="spice">Spiciest</option><option value="impact">Biggest emotional impact</option><option value="liked">Liked first</option></select></label><label>Group by<select id="libraryGroup"><option value="none">No groups</option><option value="series">Series</option><option value="author">Author</option><option value="status">Reading status</option></select></label><fieldset><legend>Layout</legend><label><input type="radio" name="libraryLayout" value="list" ${prefs.layout==='list'?'checked':''}>List</label><label><input type="radio" name="libraryLayout" value="cards" ${prefs.layout==='cards'?'checked':''}>Cards</label></fieldset><label>Card size<select id="librarySize"><option value="compact">Compact</option><option value="standard">Standard</option><option value="large">Large</option></select></label><button class="primary-button" data-action="add-book">${copy('addBook')}</button></div><details class="library-display-options"><summary>Choose what appears on cards and lists</summary><div>${visibility.map(([label,key])=>`<label class="form-check"><input type="checkbox" data-library-field="${key}" ${prefs[key]?'checked':''}>${label}</label>`).join('')}</div></details><div class="panel book-library" id="bookList"></div>`;
  const list=el.querySelector('#bookList'),search=el.querySelector('#bookSearch'),sort=el.querySelector('#librarySort'),group=el.querySelector('#libraryGroup'),size=el.querySelector('#librarySize');sort.value=prefs.sort;group.value=prefs.group;size.value=prefs.size;
  const draw=()=>{const q=search.value.toLowerCase(),score=(book,key)=>Number(book[key])||0,f=state.books.filter(b=>`${b.title} ${b.author||''} ${b.series||''}`.toLowerCase().includes(q));f.sort((a,b)=>prefs.sort==='title'?a.title.localeCompare(b.title):prefs.sort==='author'?String(a.author||'').localeCompare(String(b.author||'')):prefs.sort==='status'?String(a.status||'').localeCompare(String(b.status||'')):prefs.sort==='rating'?score(b,'rating')-score(a,'rating'):prefs.sort==='spice'?score(b,'spiceRating')-score(a,'spiceRating'):prefs.sort==='impact'?score(b,'emotionalImpact')-score(a,'emotionalImpact'):prefs.sort==='liked'?Number(b.liked==='yes')-Number(a.liked==='yes'):(Number(b.createdAt)||0)-(Number(a.createdAt)||0));list.className=`panel book-library layout-${prefs.layout} size-${prefs.size} ${prefs.group==='none'?'':'is-grouped'}`;if(!f.length)list.innerHTML=`<div class="empty-state"><h3>${copy('noBooks')}</h3><button class="primary-button" data-action="add-book">${copy('addBook')}</button></div>`;else if(prefs.group==='none')list.innerHTML=f.map(b=>bookCard(b,false)).join('');else{const groups=new Map();f.forEach(book=>{const key=prefs.group==='series'?(book.series||'No series'):prefs.group==='author'?(book.author||'Unknown author'):(book.status||'No status');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(book);});list.innerHTML=[...groups.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([name,books])=>`<section class="book-group"><header><p class="eyebrow">${prefs.group}</p><h3>${esc(name)}</h3><span>${books.length} book${books.length===1?'':'s'}</span></header><div class="book-group-items">${books.map(book=>bookCard(book,false)).join('')}</div></section>`).join('');}bindActions(list);};
  search.oninput=draw;sort.onchange=()=>{prefs.sort=sort.value;saveState();draw();};group.onchange=()=>{prefs.group=group.value;saveState();draw();};size.onchange=()=>{prefs.size=size.value;saveState();draw();};el.querySelectorAll('[name="libraryLayout"]').forEach(input=>input.onchange=()=>{prefs.layout=input.value;saveState();draw();});el.querySelectorAll('[data-library-field]').forEach(input=>input.onchange=()=>{prefs[input.dataset.libraryField]=input.checked;saveState();draw();});draw();bindActions(el);
}
function bookCard(b,compact){
  const prefs=compact?{showCover:true,showCreator:true,showStatus:true,showProgress:true,showRating:true,showSpice:true,showImpact:true,showLiked:true}:(state.libraryPreferences||{}),liked={yes:'Loved it',no:'Not for me',mixed:'Mixed feelings'}[b.liked]||'',rating=Number(b.rating)||0,spice=Number(b.spiceRating)||0,impact=Number(b.emotionalImpact)||0,showCover=prefs.showCover!==false;
  return `<article class="book-card ${compact?'is-compact-dashboard':''} ${showCover?'':'no-cover'}">${showCover?(b.coverImage?`<img class="book-cover book-cover-image" src="${esc(b.coverImage)}" alt="Cover of ${esc(b.title)}">`:`<div class="book-cover">${esc(b.title)}</div>`):''}<div class="book-info"><h4>${esc(b.title)}</h4>${prefs.showCreator!==false?`<p>${esc(b.author||'Unknown author')}${b.series?` · ${esc(b.series)}`:''}</p>`:''}<div class="book-reactions">${prefs.showRating!==false&&rating?`<span aria-label="Rated ${rating} out of 5">★ ${rating}/5</span>`:''}${prefs.showSpice!==false&&spice?`<span aria-label="Spice rating ${spice} out of 5">🌶 ${spice}/5</span>`:''}${prefs.showImpact!==false&&impact?`<span aria-label="Emotional impact ${impact} out of 5">♥ ${impact}/5</span>`:''}${prefs.showLiked!==false&&liked?`<span class="liked-${b.liked}">${liked}</span>`:''}</div>${prefs.showStatus!==false?`<span class="status-pill">${esc(b.status||'want')}</span>`:''}${prefs.showProgress!==false?`<div class="progress-track"><div class="progress-fill" style="width:${b.progress||0}%"></div></div>`:''}</div><div class="book-actions"><button class="small-button" data-action="progress-book" data-id="${b.id}">${b.progress||0}%</button>${compact?'':`<button class="small-button" data-action="edit-book" data-id="${b.id}">Rate & edit</button>`}<button class="small-button" data-action="pin-book" data-id="${b.id}">Pin to wall</button>${b.status!=='completed'?`<button class="small-button" data-action="complete-book" data-id="${b.id}">Complete</button>`:''}${compact?'':`<button class="small-button" data-action="delete-book" data-id="${b.id}">Delete</button>`}</div></article>`;
}
function renderSession(){const el=document.getElementById('session');const active=state.books.find(b=>b.status==='reading');if(!active){el.innerHTML=`<div class="empty-state"><h3>No active reading assignment</h3><button class="primary-button" data-action="add-book">${copy('addBook')}</button></div>`;bindActions(el);return;}const running=!!state.currentSession;el.innerHTML=`<div class="panel session-card"><p class="eyebrow">${esc(active.title)}</p><h3>Chapter ${esc(active.chapter||'unknown')} · ${active.progress||0}%</h3><div class="timer" id="timerDisplay">${formatTime(running?sessionSeconds:0)}</div><div class="button-row" style="justify-content:center"><button class="primary-button" id="sessionToggle">${running?'End Session':copy('startSession')}</button><button class="secondary-button" data-action="progress-book" data-id="${active.id}">Update Progress</button></div><div class="quick-grid">${['Theory','Suspicion','Important clue','Character update','Quote','Prediction','Dragon','Artifact'].map(x=>`<button class="quick-choice" data-quick="${x}">${x}</button>`).join('')}</div></div>`;el.querySelector('#sessionToggle').addEventListener('click',()=>running?endSession():startSession(active));el.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>openQuickMark(b.dataset.quick,active.id)));bindActions(el);if(running)startTimer();}
function formatTime(s){return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':');}
function startSession(b){state.currentSession={id:uid(),bookId:b.id,startedAt:Date.now()};saveState();award(2,'Reading session begun.');renderSession();}
function startTimer(){clearInterval(sessionTimer);sessionTimer=setInterval(()=>{if(!state.currentSession)return;sessionSeconds=Math.floor((Date.now()-state.currentSession.startedAt)/1000);const d=document.getElementById('timerDisplay');if(d)d.textContent=formatTime(sessionSeconds);},1000);}
function endSession(){clearInterval(sessionTimer);const d=Math.floor((Date.now()-state.currentSession.startedAt)/1000);state.sessions.push({...state.currentSession,duration:d,endedAt:Date.now()});state.currentSession=null;sessionSeconds=0;saveState();award(Math.max(4,Math.min(30,Math.round(d/900)*4)),'Session recorded.');renderSession();}

function renderTheories(){const el=document.getElementById('theories');el.innerHTML=`<div class="toolbar"><div><p class="eyebrow">Structured intelligence</p><h3>${copy('navTheories')}</h3></div><div class="button-row"><button class="secondary-button" data-action="quick-suspicion">New Suspicion</button><button class="primary-button" data-action="add-theory">${copy('addTheory')}</button></div></div><div class="intel-columns"><section><h3>Theories</h3>${state.theories.slice().reverse().map(theoryCard).join('')||`<div class="empty-state"><p>${copy('noTheories')}</p></div>`}</section><section><h3>Suspicions</h3>${state.suspicions.slice().reverse().map(suspicionCard).join('')||`<div class="empty-state"><p>No suspicions captured yet.</p></div>`}</section></div>`;bindActions(el);}
function theoryCard(t){const b=state.books.find(x=>x.id===t.bookId);return `<article class="theory-card"><h4>${esc(t.statement)}</h4><p>${esc(t.notes||'')}</p><div class="confidence"><small>Confidence ${t.confidence||50}%</small><div class="confidence-bar"><span style="width:${t.confidence||50}%"></span></div></div><div class="theory-meta"><span class="tag">${esc(t.status||'Under investigation')}</span>${b?`<span class="tag">${esc(b.title)}</span>`:''}<button class="small-button" data-action="pin-theory" data-id="${t.id}">Pin to wall</button><button class="small-button" data-action="delete-theory" data-id="${t.id}">Delete</button></div></article>`;}
function suspicionCard(s){const b=state.books.find(x=>x.id===s.bookId);return `<article class="theory-card suspicion-card"><h4>${esc(s.text)}</h4><div class="theory-meta">${b?`<span class="tag">${esc(b.title)}</span>`:''}${s.chapter?`<span class="tag">Ch. ${esc(s.chapter)}</span>`:''}<button class="small-button" data-action="promote-suspicion" data-id="${s.id}">Develop theory</button><button class="small-button" data-action="pin-suspicion" data-id="${s.id}">Pin to wall</button><button class="small-button" data-action="delete-suspicion" data-id="${s.id}">Delete</button></div></article>`;}

function renderWall(){const el=document.getElementById('wall');const wall=activeWall();const cards=state.wallCards.filter(c=>c.wallId===wall.id);const links=state.wallLinks.filter(l=>l.fromWallId===wall.id||l.toWallId===wall.id);el.innerHTML=`<div class="wall-tabs"><div class="wall-tab-scroll">${state.walls.map(w=>`<button class="wall-tab ${w.id===wall.id?'is-active':''}" data-action="switch-wall" data-id="${w.id}">${esc(w.name)}</button>`).join('')}</div><button class="small-button" data-action="new-wall">＋ Wall</button><button class="small-button" data-action="edit-wall">Edit</button></div><div class="wall-toolbar"><div><p class="eyebrow">${esc(wall.description||'Cross-linked evidence board')}</p><strong>${cards.length} cards · ${links.length} linked connections</strong></div><div class="button-row"><button class="primary-button" data-action="add-wall-card">Add Card</button><button class="secondary-button" data-action="create-link">Link Cards</button><button class="secondary-button" data-action="wall-index">Connection Index</button></div></div><div class="wall-board" id="wallBoard"><svg class="wall-lines" id="wallLines" aria-hidden="true"></svg>${cards.length?'':`<div class="wall-empty"><div><h3>This wall is waiting for evidence.</h3><p>Add custom cards, books, suspicions, theories, creatures, or any category you create.</p></div></div>`}${cards.map(wallCardHtml).join('')}</div>`;bindActions(el);enableWallDragging();requestAnimationFrame(drawWallLinks);}
function activeWall(){return state.walls.find(w=>w.id===state.activeWallId)||state.walls[0];}
function wallCardHtml(c){const incoming=state.wallLinks.filter(l=>l.toCardId===c.id).length,outgoing=state.wallLinks.filter(l=>l.fromCardId===c.id).length;return `<article class="wall-card" data-card-id="${c.id}" data-type="${esc(c.category||'Custom')}" style="left:${c.x||30}px;top:${c.y||30}px;--rot:${c.rot||0}deg"><span class="wall-pin"></span><small>${esc(c.category||'Custom')}</small><h4>${esc(c.title)}</h4><p>${esc(c.text||'')}</p><footer><button class="card-link-count" data-action="card-links" data-id="${c.id}">${incoming+outgoing} links</button><button class="card-menu" data-action="edit-wall-card" data-id="${c.id}">•••</button></footer></article>`;}
function enableWallDragging(){const board=document.getElementById('wallBoard');if(!board)return;board.querySelectorAll('.wall-card').forEach(card=>{let drag=false,sx=0,sy=0,ox=0,oy=0;const move=e=>{if(!drag)return;e.preventDefault();const p=e.touches?.[0]||e;const r=board.getBoundingClientRect();const x=Math.max(0,Math.min(r.width-card.offsetWidth,ox+p.clientX-sx));const y=Math.max(0,Math.min(r.height-card.offsetHeight,oy+p.clientY-sy));card.style.left=x+'px';card.style.top=y+'px';const d=state.wallCards.find(c=>c.id===card.dataset.cardId);d.x=x;d.y=y;drawWallLinks();};const up=()=>{if(drag){drag=false;saveState();}document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);document.removeEventListener('touchmove',move);document.removeEventListener('touchend',up);};const down=e=>{if(e.target.closest('button'))return;const p=e.touches?.[0]||e;drag=true;sx=p.clientX;sy=p.clientY;ox=parseFloat(card.style.left)||0;oy=parseFloat(card.style.top)||0;document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);document.addEventListener('touchmove',move,{passive:false});document.addEventListener('touchend',up);};card.addEventListener('mousedown',down);card.addEventListener('touchstart',down,{passive:true});});}
function drawWallLinks(){const svg=document.getElementById('wallLines'),board=document.getElementById('wallBoard');if(!svg||!board)return;const wallId=activeWall().id;const visible=new Map([...board.querySelectorAll('.wall-card')].map(e=>[e.dataset.cardId,e]));svg.setAttribute('viewBox',`0 0 ${board.clientWidth} ${board.clientHeight}`);svg.innerHTML=state.wallLinks.filter(l=>l.fromWallId===wallId&&l.toWallId===wallId).map(l=>{const a=visible.get(l.fromCardId),b=visible.get(l.toCardId);if(!a||!b)return'';const x1=a.offsetLeft+a.offsetWidth/2,y1=a.offsetTop+a.offsetHeight/2,x2=b.offsetLeft+b.offsetWidth/2,y2=b.offsetTop+b.offsetHeight/2;return `<g><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"></line><text x="${(x1+x2)/2}" y="${(y1+y2)/2-6}">${esc(l.type||'linked')}</text></g>`;}).join('');}

function renderProfile(){const p=path(),bond=state.profile.bond&&!state.profile.bond.sealed?state.profile.bond:null;const eventPending=['rider','gryphon'].includes(state.profile.path)&&!state.profile.eventComplete;const creatureLabel=bond?.type==='Dragon'?'Dragon':bond?.type==='Gryphon'?'Gryphon':'Wyvern';document.getElementById('profile').innerHTML=`<div class="profile-layout"><section class="panel identity-card"><div class="identity-sigil">${p.glyph}</div><p class="eyebrow">${p.short}</p><h3>${esc(state.profile.name)}</h3><div class="tag">${currentRank()}</div><p>${state.profile.points.toLocaleString()} ${p.progressName}</p>${bond?`<div class="bond-card">${bond.creatureImage?`<img class="bond-image" src="${bond.creatureImage}" alt="Uploaded image of ${esc(bond.name)}">`:''}<h4>${esc(bond.name)}</h4><p>${esc(bond.color)} ${esc(bond.type)} · ${esc(bond.subtype)}</p><strong>${esc(bond.ability)}</strong><p>${esc(bond.abilityDesc)}</p><div class="bond-upload-grid"><label class="upload-tile"><span>${bond.creatureImage?'Replace':'Upload'} ${creatureLabel} Image</span><input type="file" accept="image/*" data-bond-upload="creatureImage"></label><label class="upload-tile">${bond.relicImage?`<img src="${bond.relicImage}" alt="Uploaded relic image">`:''}<span>${bond.relicImage?'Replace':'Upload'} Relic Image</span><input type="file" accept="image/*" data-bond-upload="relicImage"></label></div></div>`:eventPending?`<div class="sealed-result"><strong>Assessment sealed</strong><p>Your bond and ability will be revealed after ${p.event}.</p><p><small>${Math.max(0,p.thresholds[2]-state.profile.points).toLocaleString()} ${p.progressName} remain before the event can begin.</small></p>${state.profile.points>=p.thresholds[2]?`<button class="primary-button" data-action="path-event">Begin ${p.event}</button>`:''}</div>`:''}<button class="secondary-button" data-action="change-path">Change Path Theme</button></section><section class="panel"><h3>Rank Progression</h3><div class="rank-list">${p.ranks.map((r,i)=>`<div class="rank-row ${i<=state.profile.rankIndex?'is-earned':''}"><span class="rank-dot">${i<=state.profile.rankIndex?'✓':i+1}</span><div><strong>${r}</strong><small>${i===state.profile.rankIndex?'Current rank':i<state.profile.rankIndex?'Earned':`${p.thresholds[i].toLocaleString()} ${p.progressName}`}</small></div></div>`).join('')}</div></section></div>`;const root=document.getElementById('profile');bindActions(root);root.querySelectorAll('[data-bond-upload]').forEach(input=>input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;try{state.profile.bond[input.dataset.bondUpload]=await compressImage(file);saveState();renderProfile();showToast('Bond record image saved locally.');}catch(e){showToast(e.message||'Image could not be saved.');}}));}

function bindActions(root){root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();handleAction(b.dataset.action,b.dataset.id);}));}
function handleAction(a,id){({
  'add-book':()=>openBookForm(),'edit-book':()=>openBookForm(state.books.find(book=>book.id===id)),'progress-book':()=>openProgressForm(id),'complete-book':()=>completeBook(id),'delete-book':()=>deleteItem('books',id),'pin-book':()=>openPinSource('book',id),
  'add-theory':()=>openTheoryForm(),'delete-theory':()=>deleteItem('theories',id),'pin-theory':()=>openPinSource('theory',id),'quick-suspicion':()=>openQuickMark('Suspicion'),'pin-suspicion':()=>openPinSource('suspicion',id),'delete-suspicion':()=>deleteItem('suspicions',id),'promote-suspicion':()=>promoteSuspicion(id),
  'quick-mark':()=>openQuickMark(),'view-library':()=>switchView('library'),'add-wall-card':openWallCardForm,'new-wall':openWallForm,'edit-wall':()=>openWallForm(activeWall()),'switch-wall':()=>{state.activeWallId=id;saveState();renderWall();},'create-link':openLinkForm,'wall-index':openConnectionIndex,'card-links':()=>openCardLinks(id),'edit-wall-card':()=>openEditCard(id),'path-event':openPathEvent,'change-path':openPathChange
}[a]||(()=>{}))();}
function deleteItem(k,id){state[k]=state[k].filter(x=>x.id!==id);if(k==='theories'||k==='suspicions'||k==='books'){const type=k==='theories'?'theory':k==='suspicions'?'suspicion':'book';const removed=state.wallCards.filter(c=>c.sourceType===type&&c.sourceId===id).map(c=>c.id);state.wallCards=state.wallCards.filter(c=>!removed.includes(c.id));state.wallLinks=state.wallLinks.filter(l=>!removed.includes(l.fromCardId)&&!removed.includes(l.toCardId));}saveState();renderAll();}

function openBookForm(existing=null){let coverImage=existing?.coverImage||'';const authors=[...new Set(state.books.map(book=>book.author).filter(Boolean))].sort(),series=[...new Set(state.books.map(book=>book.series).filter(Boolean))].sort();modal(`<p class="eyebrow">${existing?'Book details':'New book'}</p><h2 id="formModalTitle">${existing?`Rate and edit ${esc(existing.title)}`:copy('addBook')}</h2><div class="form-grid book-editor"><label class="form-group"><span class="field-label">Title</span><input class="text-input" id="bTitle" value="${esc(existing?.title||'')}"></label><label class="form-group"><span class="field-label">Author</span><input class="text-input" id="bAuthor" list="bookAuthorChoices" value="${esc(existing?.author||'')}" autocomplete="off"><datalist id="bookAuthorChoices">${authors.map(author=>`<option value="${esc(author)}"></option>`).join('')}</datalist></label><label class="form-group"><span class="field-label">Series</span><input class="text-input" id="bSeries" list="bookSeriesChoices" value="${esc(existing?.series||'')}" autocomplete="off"><datalist id="bookSeriesChoices">${series.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist></label><label class="form-group"><span class="field-label">Status</span><select class="select-input" id="bStatus"><option value="reading">Currently reading</option><option value="want">Want to read</option><option value="paused">Paused</option><option value="completed">Completed</option><option value="dnf">DNF</option></select></label><label class="form-group full"><span class="field-label">Cover image URL</span><input class="text-input" id="bCover" value="${esc(existing?.coverImage?.startsWith('data:')?'':existing?.coverImage||'')}" placeholder="https://…"></label><label class="form-group full book-cover-upload"><span class="field-label">Or upload a cover image</span><input type="file" id="bCoverFile" accept="image/*"><small id="bCoverStatus">${coverImage?'A cover image is saved.':'No cover image selected.'}</small></label><fieldset class="book-rating-grid full"><legend>Your reaction</legend><label>Overall rating<select id="bRating"><option value="0">Not rated</option>${[1,1.5,2,2.5,3,3.5,4,4.5,5].map(value=>`<option value="${value}" ${Number(existing?.rating)===value?'selected':''}>${value} / 5</option>`).join('')}</select></label><label class="rating-slider">Spice rating <output id="bSpiceOutput">${Number(existing?.spiceRating)||0} / 5</output><input id="bSpice" type="range" min="0" max="5" step="1" value="${Number(existing?.spiceRating)||0}" aria-describedby="bSpiceOutput"><span>None <b>🌶🌶🌶🌶🌶</b></span></label><label class="rating-slider">Emotional impact <output id="bImpactOutput">${Number(existing?.emotionalImpact)||0} / 5</output><input id="bImpact" type="range" min="0" max="5" step="1" value="${Number(existing?.emotionalImpact)||0}" aria-describedby="bImpactOutput"><span>Unshaken <b>Devastated</b></span></label><label>Did you like it?<select id="bLiked"><option value="">Not answered</option><option value="yes">Yes — loved it</option><option value="mixed">Mixed feelings</option><option value="no">No — not for me</option></select></label></fieldset><button class="primary-button full" id="saveBook">${existing?'Save Book Details':'Save Book'}</button></div>`);document.getElementById('bStatus').value=existing?.status||'reading';document.getElementById('bLiked').value=existing?.liked||'';document.getElementById('bSpice').oninput=event=>document.getElementById('bSpiceOutput').value=`${event.target.value} / 5`;document.getElementById('bImpact').oninput=event=>document.getElementById('bImpactOutput').value=`${event.target.value} / 5`;document.getElementById('bCoverFile').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{coverImage=await compressImage(file);document.getElementById('bCoverStatus').textContent='Cover image ready to save.';}catch(error){showToast(error.message||'Cover image could not be saved.');}};document.getElementById('saveBook').onclick=()=>{const title=document.getElementById('bTitle').value.trim();if(!title)return;const url=v('bCover'),data={title,author:v('bAuthor'),series:v('bSeries'),status:v('bStatus'),coverImage:url||coverImage,rating:Number(v('bRating'))||0,spiceRating:Number(v('bSpice'))||0,emotionalImpact:Number(v('bImpact'))||0,liked:v('bLiked'),updatedAt:Date.now()};if(existing)Object.assign(existing,data);else state.books.push({id:uid(),...data,progress:data.status==='completed'?100:0,chapter:'',createdAt:Date.now()});saveState();closeModal();if(!existing)award(5,'Book added.');renderAll();};}
function openProgressForm(id){const b=state.books.find(x=>x.id===id);if(!b)return;modal(`<p class="eyebrow">${esc(b.title)}</p><h2 id="formModalTitle">Update Progress</h2><label class="form-group"><span class="field-label">Progress percent</span><input type="number" min="0" max="100" class="number-input" id="progressValue" value="${b.progress||0}"></label><label class="form-group"><span class="field-label">Current chapter</span><input class="text-input" id="chapterValue" value="${esc(b.chapter||'')}"></label><button class="primary-button full-width" id="saveProgress">Save</button>`);document.getElementById('saveProgress').onclick=()=>{const old=b.progress||0;b.progress=Math.max(0,Math.min(100,Number(v('progressValue'))||0));b.chapter=v('chapterValue');if(b.progress>0&&b.status==='want')b.status='reading';saveState();closeModal();award(Math.max(1,Math.round(Math.max(0,b.progress-old)/5)),'Progress secured.');renderAll();};}
function completeBook(id){const b=state.books.find(x=>x.id===id);if(!b)return;b.status='completed';b.progress=100;saveState();award(120,copy('completeBook'));renderAll();}
function openTheoryForm(prefill='',bookId=''){modal(`<p class="eyebrow">Theory ledger</p><h2 id="formModalTitle">${copy('addTheory')}</h2><label class="form-group"><span class="field-label">Theory statement</span><textarea class="text-area" id="tStatement">${esc(prefill)}</textarea></label><label class="form-group"><span class="field-label">Source book</span><select class="select-input" id="tBook"><option value="">No book</option>${bookOptions(bookId)}</select></label><div class="form-grid"><label class="form-group"><span class="field-label">Confidence</span><input type="range" id="tConfidence" min="0" max="100" value="50"></label><label class="form-group"><span class="field-label">Status</span><select class="select-input" id="tStatus">${['Fleeting suspicion','Under investigation','Strong possibility','Nearly certain','Confirmed','Partially confirmed','Disproven','Technically correct, catastrophically misunderstood'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><label class="form-group"><span class="field-label">Reasoning and evidence</span><textarea class="text-area" id="tNotes"></textarea></label><button class="primary-button full-width" id="saveTheory">${copy('saveTheory')}</button>`);document.getElementById('saveTheory').onclick=()=>{const statement=v('tStatement');if(!statement)return;state.theories.push({id:uid(),statement,bookId:v('tBook'),confidence:Number(v('tConfidence')),status:v('tStatus'),notes:v('tNotes'),createdAt:Date.now()});saveState();closeModal();award(12,copy('success'));renderAll();};}
function openQuickMark(type='Suspicion',bookId=''){modal(`<p class="eyebrow">Quick Mark · ${esc(type)}</p><h2 id="formModalTitle">Capture it before it disappears</h2><label class="form-group"><span class="field-label">What did you notice?</span><textarea class="text-area" id="quickText"></textarea></label><label class="form-group"><span class="field-label">Source book</span><select class="select-input" id="quickBook"><option value="">No book</option>${bookOptions(bookId||state.books.find(b=>b.status==='reading')?.id)}</select></label><label class="form-group"><span class="field-label">Chapter or location</span><input class="text-input" id="quickChapter"></label><label class="form-check"><input type="checkbox" id="quickPin"><span>Pin to a conspiracy wall now</span></label><button class="primary-button full-width" id="saveQuick">Save Quick Mark</button>`);document.getElementById('saveQuick').onclick=()=>{const text=v('quickText');if(!text)return;const item={id:uid(),text,bookId:v('quickBook'),chapter:v('quickChapter'),type,createdAt:Date.now()};if(type==='Theory'){closeModal();return openTheoryForm(text,item.bookId);}state.suspicions.push(item);saveState();if(document.getElementById('quickPin').checked){closeModal();openPinSource('suspicion',item.id);}else{closeModal();award(4,'Suspicion secured.');renderAll();}};}
function promoteSuspicion(id){const s=state.suspicions.find(x=>x.id===id);if(s)openTheoryForm(s.text,s.bookId);}
function bookOptions(selected=''){return state.books.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${esc(b.title)}</option>`).join('');}

function openWallForm(existing=null){modal(`<p class="eyebrow">Wall management</p><h2 id="formModalTitle">${existing?'Edit':'Create'} Wall</h2><label class="form-group"><span class="field-label">Wall name</span><input class="text-input" id="wName" value="${esc(existing?.name||'')}"></label><label class="form-group"><span class="field-label">Purpose</span><textarea class="text-area" id="wDesc">${esc(existing?.description||'')}</textarea></label><label class="form-group"><span class="field-label">Card categories, comma separated</span><textarea class="text-area" id="wCats">${esc((existing?.categories||activeWall().categories).join(', '))}</textarea></label><button class="primary-button full-width" id="saveWall">Save Wall</button>`);document.getElementById('saveWall').onclick=()=>{const name=v('wName');if(!name)return;const data={name,description:v('wDesc'),categories:v('wCats').split(',').map(x=>x.trim()).filter(Boolean)};if(existing)Object.assign(existing,data);else{const w={id:uid(),...data};state.walls.push(w);state.activeWallId=w.id;}saveState();closeModal();renderWall();};}
function openWallCardForm(){const w=activeWall();modal(`<p class="eyebrow">${esc(w.name)}</p><h2 id="formModalTitle">Add a Card</h2><div class="form-grid"><label class="form-group"><span class="field-label">Category</span><select class="select-input" id="cCategory">${w.categories.map(x=>`<option>${esc(x)}</option>`).join('')}<option value="__new">Create new category…</option></select></label><label class="form-group"><span class="field-label">New category</span><input class="text-input" id="cNewCategory" placeholder="Only if creating one"></label><label class="form-group full"><span class="field-label">Title</span><input class="text-input" id="cTitle"></label><label class="form-group full"><span class="field-label">Details</span><textarea class="text-area" id="cText"></textarea></label><button class="primary-button full" id="saveCard">Pin Card</button></div>`);document.getElementById('saveCard').onclick=()=>{let category=v('cCategory');if(category==='__new'){category=v('cNewCategory');if(category&&!w.categories.includes(category))w.categories.push(category);}const title=v('cTitle');if(!title||!category)return;state.wallCards.push({id:uid(),wallId:w.id,category,title,text:v('cText'),sourceType:'custom',x:30+Math.random()*320,y:40+Math.random()*280,rot:Math.random()*3-1.5});saveState();closeModal();renderWall();};}
function sourceData(type,id){if(type==='book'){const x=state.books.find(b=>b.id===id);return x&&{title:x.title,text:`${x.author||'Unknown author'}${x.series?' · '+x.series:''}`,category:'Book'};}if(type==='theory'){const x=state.theories.find(t=>t.id===id);return x&&{title:'Theory',text:x.statement,category:'Theory'};}if(type==='suspicion'){const x=state.suspicions.find(s=>s.id===id);return x&&{title:'Suspicion',text:x.text,category:'Suspicion'};}return null;}
function openPinSource(type,id){const src=sourceData(type,id);if(!src)return;modal(`<p class="eyebrow">Pin linked source</p><h2 id="formModalTitle">Choose a wall</h2><p><strong>${esc(src.title)}</strong><br>${esc(src.text)}</p><label class="form-group"><span class="field-label">Destination wall</span><select class="select-input" id="pinWall">${state.walls.map(w=>`<option value="${w.id}">${esc(w.name)}</option>`).join('')}</select></label><label class="form-group"><span class="field-label">Card category</span><input class="text-input" id="pinCategory" value="${src.category}"></label><button class="primary-button full-width" id="doPin">Pin to Wall</button>`);document.getElementById('doPin').onclick=()=>{const wallId=v('pinWall');if(!state.wallCards.some(c=>c.wallId===wallId&&c.sourceType===type&&c.sourceId===id))state.wallCards.push({id:uid(),wallId,category:v('pinCategory')||src.category,title:src.title,text:src.text,sourceType:type,sourceId:id,x:40+Math.random()*300,y:50+Math.random()*280,rot:Math.random()*3-1.5});state.activeWallId=wallId;saveState();closeModal();switchView('wall');};}
function allCardOptions(selected=''){return state.walls.flatMap(w=>state.wallCards.filter(c=>c.wallId===w.id).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(w.name)} › ${esc(c.category)} › ${esc(c.title)}</option>`)).join('');}
function openLinkForm(prefill=''){if(state.wallCards.length<2)return showToast('Add at least two cards before linking them.');modal(`<p class="eyebrow">Cross-wall connection</p><h2 id="formModalTitle">Link Cards</h2><label class="form-group"><span class="field-label">From</span><select class="select-input" id="lFrom">${allCardOptions(prefill)}</select></label><label class="form-group"><span class="field-label">Relationship</span><input class="text-input" id="lType" list="linkTypes" placeholder="supports, contradicts, knows…"><datalist id="linkTypes"><option>supports</option><option>contradicts</option><option>conceals</option><option>betrayed</option><option>related to</option><option>present during</option><option>possessed</option><option>possible identity</option><option>caused</option><option>unknown connection</option></datalist></label><label class="form-group"><span class="field-label">To</span><select class="select-input" id="lTo">${allCardOptions()}</select></label><label class="form-group"><span class="field-label">Why are they linked?</span><textarea class="text-area" id="lReason" placeholder="Record the evidence, logic, contradiction, or suspicion behind this connection."></textarea></label><button class="primary-button full-width" id="saveLink">Create Connection</button>`);document.getElementById('saveLink').onclick=()=>{const from=v('lFrom'),to=v('lTo');if(!from||!to||from===to)return showToast('Choose two different cards.');const a=state.wallCards.find(c=>c.id===from),b=state.wallCards.find(c=>c.id===to);state.wallLinks.push({id:uid(),fromCardId:from,toCardId:to,fromWallId:a.wallId,toWallId:b.wallId,type:v('lType')||'linked to',reason:v('lReason'),createdAt:Date.now()});saveState();closeModal();renderWall();};}
function openCardLinks(id){const c=state.wallCards.find(x=>x.id===id);const links=state.wallLinks.filter(l=>l.fromCardId===id||l.toCardId===id);modal(`<p class="eyebrow">Connection record</p><h2 id="formModalTitle">${esc(c.title)}</h2>${links.length?links.map(l=>{const other=state.wallCards.find(x=>x.id===(l.fromCardId===id?l.toCardId:l.fromCardId));const w=state.walls.find(x=>x.id===other?.wallId);return `<article class="link-record"><strong>${l.fromCardId===id?'→':'←'} ${esc(l.type)} ${esc(other?.title||'Missing card')}</strong><small>${esc(w?.name||'Unknown wall')}</small><p>${esc(l.reason||'No reason recorded.')}</p><button class="small-button" data-delete-link="${l.id}">Delete link</button></article>`;}).join(''):`<p>No connections yet.</p>`}<button class="primary-button full-width" id="linkFromCard">Link this card</button>`);document.getElementById('linkFromCard').onclick=()=>{closeModal();openLinkForm(id);};document.querySelectorAll('[data-delete-link]').forEach(b=>b.onclick=()=>{state.wallLinks=state.wallLinks.filter(l=>l.id!==b.dataset.deleteLink);saveState();closeModal();renderWall();});}
function openConnectionIndex(){const rows=state.wallLinks.map(l=>{const a=state.wallCards.find(c=>c.id===l.fromCardId),b=state.wallCards.find(c=>c.id===l.toCardId),wa=state.walls.find(w=>w.id===l.fromWallId),wb=state.walls.find(w=>w.id===l.toWallId);return `<article class="link-record"><strong>${esc(a?.title||'Missing')} <span>→ ${esc(l.type)} →</span> ${esc(b?.title||'Missing')}</strong><small>${esc(wa?.name||'')} to ${esc(wb?.name||'')}</small><p>${esc(l.reason||'No reason recorded.')}</p></article>`;}).join('');modal(`<p class="eyebrow">Global connection index</p><h2 id="formModalTitle">Every Link Across Every Wall</h2><div class="connection-index">${rows||'<p>No connections have been recorded.</p>'}</div>`);}
function openEditCard(id){const c=state.wallCards.find(x=>x.id===id);modal(`<p class="eyebrow">Edit card</p><h2 id="formModalTitle">${esc(c.title)}</h2><label class="form-group"><span class="field-label">Category</span><input class="text-input" id="ecCategory" value="${esc(c.category)}"></label><label class="form-group"><span class="field-label">Title</span><input class="text-input" id="ecTitle" value="${esc(c.title)}"></label><label class="form-group"><span class="field-label">Details</span><textarea class="text-area" id="ecText">${esc(c.text||'')}</textarea></label><div class="button-row"><button class="primary-button" id="saveEditCard">Save</button><button class="secondary-button" id="deleteCard">Delete Card</button></div>`);document.getElementById('saveEditCard').onclick=()=>{c.category=v('ecCategory');c.title=v('ecTitle');c.text=v('ecText');saveState();closeModal();renderWall();};document.getElementById('deleteCard').onclick=()=>{state.wallCards=state.wallCards.filter(x=>x.id!==id);state.wallLinks=state.wallLinks.filter(l=>l.fromCardId!==id&&l.toCardId!==id);saveState();closeModal();renderWall();};}

function openPathEvent(){
  const p=path();
  if(!['rider','gryphon'].includes(state.profile.path)||state.profile.eventComplete)return showToast(`${p.event} has already been completed.`);
  if(state.profile.points<p.thresholds[2])return showToast(`You need ${(p.thresholds[2]-state.profile.points).toLocaleString()} more ${p.progressName} before ${p.event}.`);
  if(!state.profile.assessment)return showToast('Your sealed assessment is missing. Change paths and complete onboarding again.');
  if(!state.profile.bond)state.profile.bond={...generateBondResult(state.profile.path,state.profile.assessment),sealed:true};
  const rider=state.profile.path==='rider';
  modal(`<p class="eyebrow">${p.event}</p><h2 id="formModalTitle">${rider?'Survive the field. Be chosen.':'Step from the edge and trust the bond.'}</h2><p>${rider?'Threshing is not a promotion ceremony. It is the point at which a cadet either leaves the field bonded, or does not leave it at all.':'The Leap asks for trust, conviction, and the courage to step forward without certainty.'}</p><div class="event-trials">${(rider?['Cross the parapet','Identify three threats from incomplete evidence','Choose who you protect when retreat is impossible','Face the field without knowing who will choose you']:['Complete the ascent','State the truth you would defy authority to protect','Choose trust over certainty','Take the leap']).map((x,i)=>`<label class="form-check"><input type="checkbox" class="event-check"><span>${i+1}. ${x}</span></label>`).join('')}</div><button type="button" class="primary-button full-width" id="completeEvent">Complete ${p.event}</button>`);
  const button=document.getElementById('completeEvent');
  button.addEventListener('click',()=>{
    const eventModal=document.getElementById('formModal');const checks=[...eventModal.querySelectorAll('.event-check')];
    if(!checks.length||checks.some(x=>!x.checked))return showToast('Complete every stage of the event.');
    state.profile.eventComplete=true;
    state.profile.bond.sealed=false;
    state.profile.rankIndex=2;
    state.profile.points=Math.max(state.profile.points,p.thresholds[2]);
    state.profile.pendingBondReveal=true;
    state.profile.bondRevealSeen=false;
    saveState();
    closeModal();
    renderAll();
    requestAnimationFrame(()=>setTimeout(showBondingRevealModal,40));
  });
}

function showBondingRevealModal(){
  const b=state.profile.bond,p=path();
  if(!b||b.sealed)return;
  const rider=state.profile.path==='rider';
  const title=rider?'You survived Threshing.':'You completed The Leap.';
  const bondedWord=rider?'Dragon Rider':'Bonded Flier';
  modal(`<div class="bond-reveal-modal"><div class="result-sigil">${p.glyph}</div><p class="eyebrow">Bond confirmed</p><h2 id="formModalTitle">${title}</h2><p class="bond-announcement">You are now a <strong>${bondedWord}</strong>. You are bonded to:</p><h3>${esc(b.name)}</h3><p><strong>${esc(b.color)} ${esc(b.type)}</strong> · ${esc(b.subtype)}</p><p>${esc(b.description||'')}</p><div class="reveal-signet"><small>Your signet</small><strong>${esc(b.ability)}</strong><p>${esc(b.abilityDesc)}</p></div><div class="reveal-relic"><small>Your relic</small><strong>${esc(b.relic)}</strong></div><p class="muted-copy">You can optionally upload an image of your ${b.type.toLowerCase()} and your relic from your Service Record. Creature names are unique across dragons, gryphons, and wyverns.</p><button type="button" class="primary-button full-width" id="acceptBondReveal">Enter as ${bondedWord}</button></div>`);
  document.getElementById('acceptBondReveal').addEventListener('click',()=>{state.profile.pendingBondReveal=false;state.profile.bondRevealSeen=true;saveState();closeModal();renderAll();showToast(`You are now ${p.ranks[2]}.`);});
}

function compressImage(file){return new Promise((resolve,reject)=>{if(!file.type.startsWith('image/'))return reject(new Error('Choose an image file.'));if(file.size>12*1024*1024)return reject(new Error('Choose an image smaller than 12 MB.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Image could not be read.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Image could not be opened.'));img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82));};img.src=reader.result;};reader.readAsDataURL(file);});}

function openPathChange(){persistActivePathRecord();modal(`<p class="eyebrow">Theme assignment</p><h2 id="formModalTitle">Change Path</h2><p>Every path keeps its own permanent service record. Returning to a previous path restores the exact rank, standing, assessment, event history, creature, signet, relic, and uploaded images you had before.</p><div class="path-grid">${Object.entries(PATHS).map(([k,p])=>{const saved=state.pathRecords?.[k];const subtitle=saved?(saved.bond&&!saved.bond.sealed?`${saved.bond.name} · ${saved.bond.ability}`:`Saved at ${p.ranks[saved.rankIndex||0]}`):'New path record';return `<button class="path-choice" data-new-path="${k}"><span style="font-size:30px">${p.glyph}</span><strong>${p.name}</strong><small>${esc(subtitle)}</small></button>`;}).join('')}</div>`);document.querySelectorAll('[data-new-path]').forEach(b=>b.onclick=()=>{const next=b.dataset.newPath;if(next===state.profile.path)return closeModal();persistActivePathRecord();const existed=restorePathRecord(next);saveState();closeModal();applyTheme();renderAll();if(!existed&&['rider','gryphon','dark'].includes(next)){selectedPath=next;renderQuestionnaire();setOnboardingStep(2);openModal('onboardingModal');}else if(state.profile.pendingBondReveal&&state.profile.bond&&!state.profile.bond.sealed){setTimeout(showBondingRevealModal,50);}else{showToast(existed?`${PATHS[next].name} record restored.`:`${PATHS[next].name} path opened.`);}});}

function modal(html){document.getElementById('formModalContent').innerHTML=html;openModal();}
function v(id){return document.getElementById(id)?.value?.trim?.()??document.getElementById(id)?.value??'';}

init();
